-- 10_klogi_sync_20260923.sql
-- PC 관리(ip_address)를 관리대장 엑셀(KLOGI_20260923094150.xls, 2026-09-23 추출) 기준으로 보정한다.
-- 엑셀이 현재 가장 정확한 운영 원본이므로, 엑셀에 있는 값으로 덮어쓰고 엑셀에 없는 별도관리 행은 삭제한다.
--
-- 컬럼 매핑 (엑셀 → ip_address)
--   IP그룹+IP → IP_ADDRESS / IP_GROUP,  상주/임시 → USAGE_TYPE,  부서 → DEPARTMENT,  서버구분 → DEVICE,
--   구입업체 → VENDOR(+RENTAL_COMPANY 파생),  모델 → MODEL,  제조번호 → SERIAL_NO,  사용자 → USER_NAME,
--   OS버전(OEM) → OS_VERSION,  OS S/N(OEM) → OS_SERIAL,  설치된 OFFICE 버전 → OFFICE_VERSION,
--   OFFICE S/N(DSP) → OFFICE_SERIAL,  설치된 한글 버전 → HANGUL_VERSION,  한글S/N → HANGUL_SERIAL,  참고사항 → REMARK
--   (암호·구입가격·REMARKS/ATTR 컬럼은 대상 아님)
--
-- 처리 내용
--   1) IP 있는 행: IP별로 엑셀 값과 다른 행만 갱신. 엑셀에서 빈 IP는 사용자·장치·스펙을 비우고 AVAILABLE.
--      상태: 반납 → RECLAIMED, 사용자 있음 → IN_USE, 없음 → AVAILABLE (IpAddress.update() 규칙과 동일)
--   2) 엑셀에만 있는 IP: 신규 등록
--   3) IP 없는 행(별도관리): 제조번호(중복 시 제조번호+구분, 제조번호 없으면 부서+장치+사용자)로 짝을 지어 갱신,
--      엑셀에만 있으면 신규 등록, DB에만 있으면 ip_history 와 함께 삭제
--   ip_history 에는 보정 이력을 남기지 않는다. 변경 행은 UPDATED_BY/CREATED_BY = 'klogi_sync'.
--
-- 1회성 보정: 이미 적용된 DB(ip_address 에 CREATED_BY/UPDATED_BY = 'klogi_sync' 행이 있음)에서는 아무 것도 하지 않는다.
--   (재실행 시 그 사이 새로 등록한 별도관리 장비를 지우거나 화면에서 고친 값을 엑셀 값으로 되돌리지 않도록)
-- 폐기된 별도관리 Win 7 노트북(11번 대상)은 등록하지 않으므로 10·11 실행 순서와 무관하게 결과가 같다.
-- 실행: mariadb --default-character-set=utf8mb4 -u platform_user -p platform_db < sql/module-kims/10_klogi_sync_20260923.sql

SET NAMES utf8mb4;
SET @run_at := NOW();
SET @klogi_applied := EXISTS (SELECT 1 FROM ip_address WHERE CREATED_BY = 'klogi_sync' OR UPDATED_BY = 'klogi_sync');
SELECT IF(@klogi_applied, '10_klogi_sync: 이미 적용된 DB — 변경 없이 종료', '10_klogi_sync: 보정 시작') AS message;

DROP TABLE IF EXISTS tmp_klogi_src, tmp_klogi_ip, tmp_klogi_sep, tmp_klogi_map;

CREATE TABLE tmp_klogi_src (
  SRC_ID          INT          NOT NULL PRIMARY KEY,
  IP_GROUP        VARCHAR(30),
  IP_LAST         VARCHAR(10),
  USAGE_TYPE      VARCHAR(20),
  DEPARTMENT      VARCHAR(50),
  DEVICE          VARCHAR(100),
  VENDOR          VARCHAR(100),
  MODEL           VARCHAR(100),
  SERIAL_NO       VARCHAR(100),
  USER_NAME       VARCHAR(100),
  OS_VERSION      VARCHAR(200),
  OS_SERIAL       VARCHAR(100),
  OFFICE_VERSION  VARCHAR(60),
  OFFICE_SERIAL   VARCHAR(100),
  HANGUL_VERSION  VARCHAR(60),
  HANGUL_SERIAL   VARCHAR(100),
  REMARK          VARCHAR(500)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

;

-- 파생 컬럼: 전체 IP, 데이터 유무, 렌탈사, OS 버전 길이 보정(컬럼 60자)
ALTER TABLE tmp_klogi_src
  ADD COLUMN FULL_IP        VARCHAR(45),
  ADD COLUMN HAS_DATA       TINYINT NOT NULL DEFAULT 0,
  ADD COLUMN RENTAL_COMPANY VARCHAR(100),
  ADD COLUMN NEW_STATUS     VARCHAR(20);

UPDATE tmp_klogi_src SET
  IP_GROUP       = TRIM(TRAILING '.' FROM IP_GROUP),
  OS_VERSION     = LEFT(OS_VERSION, 60),
  HAS_DATA       = (COALESCE(USAGE_TYPE, DEPARTMENT, DEVICE, MODEL, SERIAL_NO, USER_NAME) IS NOT NULL),
  RENTAL_COMPANY = CASE VENDOR WHEN 'AJ네트웍스' THEN 'AJ렌탈' WHEN '렌탈' THEN '기재요망' ELSE VENDOR END,
  NEW_STATUS     = CASE WHEN USAGE_TYPE = '반납' THEN 'RECLAIMED'
                        WHEN USER_NAME IS NOT NULL THEN 'IN_USE' ELSE 'AVAILABLE' END;
UPDATE tmp_klogi_src SET FULL_IP = CONCAT(IP_GROUP, '.', IP_LAST)
 WHERE IP_GROUP REGEXP '^[0-9]+\\.[0-9]+\\.[0-9]+$' AND IP_LAST REGEXP '^[0-9]+$';

-- 폐기된 별도관리 Win 7 노트북은 등록 대상에서 제외 (11번과 같은 조건)
DELETE FROM tmp_klogi_src
 WHERE FULL_IP IS NULL AND DEVICE = '노트북' AND OS_VERSION LIKE 'Win 7%';

-- 이미 적용된 DB 면 원본을 비워 아래 갱신·등록이 일어나지 않게 한다 (삭제문은 별도로 @klogi_applied 조건을 건다)
DELETE FROM tmp_klogi_src WHERE @klogi_applied = 1;

-- ============================================================
-- 1) IP 있는 행 — 같은 IP가 여러 줄이면 데이터 있는 줄(없으면 첫 줄)을 대표로
-- ============================================================
CREATE TABLE tmp_klogi_ip ENGINE=InnoDB AS
SELECT s.* FROM tmp_klogi_src s
JOIN (SELECT FULL_IP, MAX(IF(HAS_DATA = 1, SRC_ID, NULL)) AS D, MIN(SRC_ID) AS F
        FROM tmp_klogi_src WHERE FULL_IP IS NOT NULL GROUP BY FULL_IP) p
  ON s.SRC_ID = COALESCE(p.D, p.F);
ALTER TABLE tmp_klogi_ip ADD UNIQUE KEY (FULL_IP);

-- 구입업체가 바뀌는 행만 렌탈사 재산정 (렌탈사를 화면에서 따로 고친 행은 보존)
UPDATE ip_address a JOIN tmp_klogi_ip s ON a.IP_ADDRESS = s.FULL_IP
   SET a.RENTAL_COMPANY = s.RENTAL_COMPANY
 WHERE NOT (a.VENDOR <=> s.VENDOR);

-- 사용자가 바뀌면 사용자ID는 더 이상 맞지 않으므로 비움
UPDATE ip_address a JOIN tmp_klogi_ip s ON a.IP_ADDRESS = s.FULL_IP
   SET a.USER_ID = NULL
 WHERE NOT (a.USER_NAME <=> s.USER_NAME);

-- 엑셀에서 빈 IP → 자산번호·렌탈사도 비움 (IpAddress.vacate() 와 동일 범위)
UPDATE ip_address a JOIN tmp_klogi_ip s ON a.IP_ADDRESS = s.FULL_IP
   SET a.RENTAL_COMPANY = NULL, a.PC_ASSET_NO = NULL, a.MONITOR_ASSET_NO = NULL
 WHERE s.HAS_DATA = 0;

UPDATE ip_address a JOIN tmp_klogi_ip s ON a.IP_ADDRESS = s.FULL_IP
   SET a.IP_GROUP       = s.IP_GROUP,
       a.USAGE_TYPE     = s.USAGE_TYPE,
       a.DEPARTMENT     = s.DEPARTMENT,
       a.DEVICE         = s.DEVICE,
       a.USER_NAME      = s.USER_NAME,
       a.MODEL          = s.MODEL,
       a.SERIAL_NO      = s.SERIAL_NO,
       a.VENDOR         = s.VENDOR,
       a.OS_VERSION     = s.OS_VERSION,
       a.OS_SERIAL      = s.OS_SERIAL,
       a.OFFICE_VERSION = s.OFFICE_VERSION,
       a.OFFICE_SERIAL  = s.OFFICE_SERIAL,
       a.HANGUL_VERSION = s.HANGUL_VERSION,
       a.HANGUL_SERIAL  = s.HANGUL_SERIAL,
       a.REMARK         = s.REMARK,
       a.STATUS         = s.NEW_STATUS,
       a.RECLAIMED_AT   = IF(s.NEW_STATUS = 'RECLAIMED', IFNULL(a.RECLAIMED_AT, CURDATE()), NULL),
       a.DELETED_YN = 'N', a.DELETED_AT = NULL, a.DELETED_BY = NULL,
       a.UPDATED_AT = @run_at, a.UPDATED_BY = 'klogi_sync'
 WHERE NOT (a.IP_GROUP <=> s.IP_GROUP AND a.USAGE_TYPE <=> s.USAGE_TYPE AND a.DEPARTMENT <=> s.DEPARTMENT
        AND a.DEVICE <=> s.DEVICE AND a.USER_NAME <=> s.USER_NAME AND a.MODEL <=> s.MODEL
        AND a.SERIAL_NO <=> s.SERIAL_NO AND a.VENDOR <=> s.VENDOR AND a.OS_VERSION <=> s.OS_VERSION
        AND a.OS_SERIAL <=> s.OS_SERIAL AND a.OFFICE_VERSION <=> s.OFFICE_VERSION
        AND a.OFFICE_SERIAL <=> s.OFFICE_SERIAL AND a.HANGUL_VERSION <=> s.HANGUL_VERSION
        AND a.HANGUL_SERIAL <=> s.HANGUL_SERIAL AND a.REMARK <=> s.REMARK AND a.DELETED_YN = 'N');

-- ============================================================
-- 2) 엑셀에만 있는 IP → 신규 등록
-- ============================================================
       MODEL, SERIAL_NO, VENDOR, OS_VERSION, OS_SERIAL, OFFICE_VERSION, OFFICE_SERIAL, HANGUL_VERSION,
       HANGUL_SERIAL, RENTAL_COMPANY, REMARK, RECLAIMED_AT, CREATED_AT, UPDATED_AT, CREATED_BY, UPDATED_BY)
SELECT s.FULL_IP, s.IP_GROUP,
       IF(s.IP_GROUP IN ('192.1.17', '192.1.104', '192.1.107', '192.1.117'), '서울', '청주'),
       s.NEW_STATUS, s.USAGE_TYPE, s.USER_NAME, s.DEPARTMENT, s.DEVICE,
       s.MODEL, s.SERIAL_NO, s.VENDOR, s.OS_VERSION, s.OS_SERIAL, s.OFFICE_VERSION, s.OFFICE_SERIAL, s.HANGUL_VERSION,
       s.HANGUL_SERIAL, s.RENTAL_COMPANY, s.REMARK, IF(s.NEW_STATUS = 'RECLAIMED', CURDATE(), NULL),
       @run_at, @run_at, 'klogi_sync', 'klogi_sync'
  FROM tmp_klogi_ip s
 WHERE NOT EXISTS (SELECT 1 FROM ip_address a WHERE a.IP_ADDRESS = s.FULL_IP);

-- ============================================================
-- 3) IP 없는 행(별도관리)
-- ============================================================
CREATE TABLE tmp_klogi_sep ENGINE=InnoDB AS
SELECT * FROM tmp_klogi_src WHERE FULL_IP IS NULL AND HAS_DATA = 1;

CREATE TABLE tmp_klogi_map (
  SRC_ID INT    NOT NULL PRIMARY KEY,
  IP_ID  BIGINT NOT NULL UNIQUE
) ENGINE=InnoDB;

-- 3-1) 제조번호가 양쪽 모두 유일하면 제조번호로
SELECT s.SRC_ID, a.IP_ID
  FROM tmp_klogi_sep s
  JOIN ip_address a ON a.IP_ADDRESS IS NULL AND a.SERIAL_NO = s.SERIAL_NO
 WHERE s.SERIAL_NO IN (SELECT SERIAL_NO FROM tmp_klogi_sep GROUP BY SERIAL_NO HAVING COUNT(*) = 1)
   AND a.SERIAL_NO IN (SELECT SERIAL_NO FROM ip_address WHERE IP_ADDRESS IS NULL GROUP BY SERIAL_NO HAVING COUNT(*) = 1);

-- 3-2) 남은 행: 제조번호 + 상주/임시 구분
SELECT s.SRC_ID, a.IP_ID
  FROM tmp_klogi_sep s
  JOIN ip_address a ON a.IP_ADDRESS IS NULL AND a.SERIAL_NO = s.SERIAL_NO AND a.USAGE_TYPE <=> s.USAGE_TYPE
 WHERE s.SRC_ID NOT IN (SELECT SRC_ID FROM tmp_klogi_map)
   AND a.IP_ID NOT IN (SELECT IP_ID FROM tmp_klogi_map)
 ORDER BY s.SRC_ID, a.IP_ID;

-- 3-3) 제조번호 없는 행: 부서 + 장치 + 사용자
SELECT s.SRC_ID, a.IP_ID
  FROM tmp_klogi_sep s
  JOIN ip_address a ON a.IP_ADDRESS IS NULL AND a.SERIAL_NO IS NULL AND s.SERIAL_NO IS NULL
                   AND a.DEPARTMENT <=> s.DEPARTMENT AND a.DEVICE <=> s.DEVICE AND a.USER_NAME <=> s.USER_NAME
 WHERE s.SRC_ID NOT IN (SELECT SRC_ID FROM tmp_klogi_map)
   AND a.IP_ID NOT IN (SELECT IP_ID FROM tmp_klogi_map)
 ORDER BY s.SRC_ID, a.IP_ID;

-- 3-4) 짝지은 행 갱신 (렌탈사·사용자ID 규칙은 1)과 동일)
UPDATE ip_address a JOIN tmp_klogi_map m ON m.IP_ID = a.IP_ID JOIN tmp_klogi_sep s ON s.SRC_ID = m.SRC_ID
   SET a.RENTAL_COMPANY = s.RENTAL_COMPANY
 WHERE NOT (a.VENDOR <=> s.VENDOR);

UPDATE ip_address a JOIN tmp_klogi_map m ON m.IP_ID = a.IP_ID JOIN tmp_klogi_sep s ON s.SRC_ID = m.SRC_ID
   SET a.USER_ID = NULL
 WHERE NOT (a.USER_NAME <=> s.USER_NAME);

UPDATE ip_address a JOIN tmp_klogi_map m ON m.IP_ID = a.IP_ID JOIN tmp_klogi_sep s ON s.SRC_ID = m.SRC_ID
   SET a.IP_GROUP       = '별도관리',
       a.USAGE_TYPE     = s.USAGE_TYPE,
       a.DEPARTMENT     = s.DEPARTMENT,
       a.DEVICE         = s.DEVICE,
       a.USER_NAME      = s.USER_NAME,
       a.MODEL          = s.MODEL,
       a.SERIAL_NO      = s.SERIAL_NO,
       a.VENDOR         = s.VENDOR,
       a.OS_VERSION     = s.OS_VERSION,
       a.OS_SERIAL      = s.OS_SERIAL,
       a.OFFICE_VERSION = s.OFFICE_VERSION,
       a.OFFICE_SERIAL  = s.OFFICE_SERIAL,
       a.HANGUL_VERSION = s.HANGUL_VERSION,
       a.HANGUL_SERIAL  = s.HANGUL_SERIAL,
       a.REMARK         = s.REMARK,
       -- 별도관리 장비는 사용자 없이도 사용중(설비 등)이므로 반납 여부만 상태에 반영
       a.STATUS         = CASE WHEN s.USAGE_TYPE = '반납' THEN 'RECLAIMED'
                               WHEN a.STATUS = 'RECLAIMED' THEN 'IN_USE' ELSE a.STATUS END,
       a.RECLAIMED_AT   = IF(s.USAGE_TYPE = '반납', IFNULL(a.RECLAIMED_AT, CURDATE()), NULL),
       a.DELETED_YN = 'N', a.DELETED_AT = NULL, a.DELETED_BY = NULL,
       a.UPDATED_AT = @run_at, a.UPDATED_BY = 'klogi_sync'
 WHERE NOT (a.IP_GROUP <=> '별도관리' AND a.USAGE_TYPE <=> s.USAGE_TYPE AND a.DEPARTMENT <=> s.DEPARTMENT
        AND a.DEVICE <=> s.DEVICE AND a.USER_NAME <=> s.USER_NAME AND a.MODEL <=> s.MODEL
        AND a.SERIAL_NO <=> s.SERIAL_NO AND a.VENDOR <=> s.VENDOR AND a.OS_VERSION <=> s.OS_VERSION
        AND a.OS_SERIAL <=> s.OS_SERIAL AND a.OFFICE_VERSION <=> s.OFFICE_VERSION
        AND a.OFFICE_SERIAL <=> s.OFFICE_SERIAL AND a.HANGUL_VERSION <=> s.HANGUL_VERSION
        AND a.HANGUL_SERIAL <=> s.HANGUL_SERIAL AND a.REMARK <=> s.REMARK AND a.DELETED_YN = 'N');

-- 3-5) DB에만 있는 별도관리 행 삭제 (이력 포함 — 앱의 행 삭제와 동일). 이번 실행에서 새로 넣을 행은 아직 없음
--      이미 적용된 DB 에서는 원본이 비어 있어 전부 삭제 대상이 되므로 반드시 @klogi_applied = 0 일 때만 실행
DELETE h FROM ip_history h JOIN ip_address a ON a.IP_ID = h.IP_ID
 WHERE @klogi_applied = 0 AND a.IP_ADDRESS IS NULL AND a.IP_ID NOT IN (SELECT IP_ID FROM tmp_klogi_map);
DELETE FROM ip_address
 WHERE @klogi_applied = 0 AND IP_ADDRESS IS NULL AND IP_ID NOT IN (SELECT IP_ID FROM tmp_klogi_map);

-- 3-6) 엑셀에만 있는 별도관리 행 → 신규 등록
       MODEL, SERIAL_NO, VENDOR, OS_VERSION, OS_SERIAL, OFFICE_VERSION, OFFICE_SERIAL, HANGUL_VERSION,
       HANGUL_SERIAL, RENTAL_COMPANY, REMARK, RECLAIMED_AT, CREATED_AT, UPDATED_AT, CREATED_BY, UPDATED_BY)
SELECT NULL, '별도관리', '청주',
       IF(s.USAGE_TYPE = '반납', 'RECLAIMED', 'IN_USE'), s.USAGE_TYPE, s.USER_NAME, s.DEPARTMENT, s.DEVICE,
       s.MODEL, s.SERIAL_NO, s.VENDOR, s.OS_VERSION, s.OS_SERIAL, s.OFFICE_VERSION, s.OFFICE_SERIAL, s.HANGUL_VERSION,
       s.HANGUL_SERIAL, s.RENTAL_COMPANY, s.REMARK, IF(s.USAGE_TYPE = '반납', CURDATE(), NULL),
       @run_at, @run_at, 'klogi_sync', 'klogi_sync'
  FROM tmp_klogi_sep s
 WHERE s.SRC_ID NOT IN (SELECT SRC_ID FROM tmp_klogi_map)
 ORDER BY s.SRC_ID;

DROP TABLE IF EXISTS tmp_klogi_src, tmp_klogi_ip, tmp_klogi_sep, tmp_klogi_map;
